using namespace std;

long long process(long long n, long long m) {
    long long minVal = min(n, m);
    long long maxVal = max(n, m);
    long long totalCells = n * m;

    if (minVal <= 3 && maxVal <= 3) {
        if (minVal == 1 || maxVal == 1) return 0;
        if (minVal == 2 && maxVal == 2) return 0;
        if (minVal == 2 && maxVal == 3) return 4;
        if (minVal == 3 && maxVal == 2) return 4;
        if (minVal == 3 && maxVal == 3) return 8;
        return 0;
    }

    if (minVal == 1) {
        long long modVal = maxVal % 6;
        if (modVal == 4) modVal = 2;
        else if (modVal == 5) modVal = 1;
        return totalCells - modVal;
    } else if (minVal == 2) {
        if (maxVal == 3 || maxVal == 7) maxVal = 2;
        else maxVal = 0;
        return totalCells - maxVal;
    } else {
        return totalCells - (totalCells % 2);
    }
}

